import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.2
.target sm_89
.address_size 64

.visible .entry triu_matmul(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    .reg .pred %p<10>;
    .reg .s32  %r<24>;
    .reg .s64  %rd<24>;
    .reg .f32  %f<8>;

    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1,  [N];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.s32 %r5, %r2, %r3, %r4;   // col

    mov.u32 %r6, %ctaid.y;
    mov.u32 %r7, %ntid.y;
    mov.u32 %r8, %tid.y;
    mad.lo.s32 %r9, %r6, %r7, %r8;   // row

    setp.ge.s32 %p1, %r5, %r1;
    setp.ge.s32 %p2, %r9, %r1;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;

    // linear index row*N+col
    mul.lo.s32 %r10, %r9, %r1;
    add.s32 %r11, %r10, %r5;
    mul.wide.s32 %rd4, %r11, 4;
    add.s64 %rd5, %rd3, %rd4;   // address of C[row][col]

    setp.lt.s32 %p4, %r5, %r9;   // col < row -> zero
    @%p4 bra STORE_ZERO;

    mov.f32 %f1, 0f00000000;
    mov.s32 %r12, %r9;    // k = row

LOOP:
    setp.gt.s32 %p5, %r12, %r5;   // k > col
    @%p5 bra STORE_SUM;

    // A index: row*N+k
    mul.lo.s32 %r13, %r9, %r1;
    add.s32 %r14, %r13, %r12;
    mul.wide.s32 %rd6, %r14, 4;
    add.s64 %rd7, %rd1, %rd6;
    ld.global.f32 %f2, [%rd7];

    // B index: k*N+col
    mul.lo.s32 %r15, %r12, %r1;
    add.s32 %r16, %r15, %r5;
    mul.wide.s32 %rd8, %r16, 4;
    add.s64 %rd9, %rd2, %rd8;
    ld.global.f32 %f3, [%rd9];

    fma.rn.f32 %f1, %f2, %f3, %f1;

    add.s32 %r12, %r12, 1;
    bra.uni LOOP;

STORE_SUM:
    st.global.f32 [%rd5], %f1;
    bra.uni DONE;

STORE_ZERO:
    mov.f32 %f4, 0f00000000;
    st.global.f32 [%rd5], %f4;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triu_matmul")

class ModelNew(nn.Module):
    """
    Custom PTX-based model that performs matrix multiplication (C = A * B)
    for upper triangular matrices, returning the upper triangular result.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 supported"
        assert A.shape == B.shape and A.dim() == 2 and A.shape[0] == A.shape[1], "Square matrices required"

        A = A.contiguous()
        B = B.contiguous()

        N = A.shape[0]

        C = torch.empty((N, N), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()

        block_x, block_y = 16, 16
        grid_x = (N + block_x - 1) // block_x
        grid_y = (N + block_y - 1) // block_y

        module.launch(
            "triu_matmul",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

